_ORDER = sorted(LABELS, key=len, reverse=True)
_TOKEN = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")


def legacy(text):
    """The original (Italian) form of a label."""
    if text in LABELS:
        return LABELS[text]
    for new in _ORDER:
        if len(new) >= 6 and new in text:
            text = text.replace(new, LABELS[new])
    return _TOKEN.sub(lambda m: NAMES.get(m.group(0), m.group(0)), text)


def crc32_legacy(data):
    """`zlib.crc32` of the original form of the label given as bytes."""
    return zlib.crc32(legacy(data.decode("utf-8")).encode("utf-8"))
